"""Self-contained, phone-friendly inventory of actual model/icon resources. No ZIP or gameplay claims."""
from pathlib import Path
from model_io import load_catalog
from PIL import Image,ImageDraw,ImageFont
import io,base64,html,json
R=Path(__file__).resolve().parents[1];out=R.parent/'game-assets';out.mkdir(exist_ok=True);d=load_catalog(R)
def category(id):
 return 'Блоки' if id<100 or id==120 else 'Оружие' if 152<=id<=165 or id==103 else 'Инструменты' if id in [100,101,102,150,151] else 'Одежда и броня' if id in [104,105,106,107,108,130,131,132] else 'Еда' if id in [110,111,112,113,114,135,138] else 'Свет' if id==148 else 'Материалы'
cards=[];names=[]
for m in d['models']:
 id=m['id'];cat=category(id);name=m['name'];names.append(dict(id=id,name=name,category=cat))
 image=Image.open(R/f'Assets/Resources/VoxelIcons/Item{id}.png').convert('RGBA').resize((192,192),Image.Resampling.LANCZOS);buf=io.BytesIO();image.save(buf,format='WEBP',quality=83,method=6)
 src='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode();note='Новые AI-текстуры' if id in [7,8,46,135,136,138,139,140,141,142,143,144,145] else 'Новые текстуры алмаза' if id in [47,48,149,151,153,155,157,159,161,163] else 'Новая геометрия · существующие материалы' if 150<=id<=165 else 'Уже есть в проекте'
 cards.append(f'<label class="card" data-name="{html.escape(name.lower())}" data-category="{cat}" data-id="{id}"><input type="checkbox" value="{id}"><span class="check">Выбрать для текстуры</span><img loading="lazy" src="{src}" alt="{html.escape(name)}"><small>#{id} · {cat}</small><h2>{html.escape(name)}</h2><p>{note}</p></label>')
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>LestingCraft — предметы</title><style>*{box-sizing:border-box}body{margin:0;background:#101a20;color:#e4ebe7;font:16px system-ui,sans-serif}header,main,footer{max-width:1200px;margin:auto;padding:24px}header{padding-top:40px}.eyebrow{color:#d8bd88;letter-spacing:.2em;font-size:12px}h1{font-size:clamp(30px,6vw,54px);margin:12px 0}header p{max-width:820px;color:#a6b9bd;line-height:1.6}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}input[type=search],select,button{font:inherit;background:#1c2d35;color:#e4ebe7;border:1px solid #45606b;border-radius:9px;padding:12px}input[type=search]{flex:1;min-width:180px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(192px,1fr));gap:14px;padding-top:0}.card{position:relative;display:block;border:1px solid #314650;border-radius:14px;padding:16px;background:linear-gradient(145deg,#1d2c32,#152229);cursor:pointer;transition:.15s}.card:has(input:checked){border-color:#ebc877;box-shadow:inset 0 0 0 1px #ebc877}.card img{width:100%;aspect-ratio:1;object-fit:contain}.card h2{font-size:17px;margin:8px 0;line-height:1.3}.card p{color:#91a8af;font-size:12px;min-height:32px}.card small{font-size:12px;color:#c6b287}.card input{position:absolute;top:16px;left:16px;accent-color:#ddbd7b;width:18px;height:18px}.check{display:block;margin-left:28px;font-size:11px;color:#9db1b5}aside{position:sticky;bottom:0;background:#102129f2;border-top:1px solid #55717b;padding:14px 24px;backdrop-filter:blur(12px)}aside .inner{max-width:1152px;margin:auto;display:flex;gap:16px;align-items:center;flex-wrap:wrap}textarea{flex:1;min-width:200px;background:#192b33;color:#f0dec0;border:1px solid #49616b;border-radius:8px;padding:10px;font:14px system-ui;height:64px}footer{color:#8da8af;font-size:13px;line-height:1.6}button{cursor:pointer}button:hover{border-color:#dbbc7d}[hidden]{display:none!important}@media(max-width:480px){header,main,footer{padding-left:14px;padding-right:14px}main{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.card{padding:10px}.card h2{font-size:14px}.card small,.check{font-size:10px}.card input{top:10px;left:10px}.check{margin-left:22px}aside{padding:10px 14px}}</style><header><div class="eyebrow">LESTINGCRAFT / NEW ERA</div><h1>Что уже есть в игре</h1><p><strong>98 моделей блоков и предметов.</strong> Здесь рендеры настоящей геометрии и текстур проекта, а не нарисованные обещания и не скриншоты запущенной игры. Отметь карточки, которым нужны новые текстуры, и пришли список номеров.</p><p>Добавлено: алмазы, железная и алмазная кирки, 12 видов клинкового и тяжёлого оружия, лук и стрелы. Теперь сгенерированы отдельные материалы металла слитков, меди, кожи, сырого и жареного мяса, воды и лавы. Металлические детали оружия тоже используют новый материал. Стекло и кристаллы прозрачные.</p><div class="tools"><input id="search" type="search" placeholder="Найти по имени или номеру…"><select id="category"><option>Все категории</option>'''+''.join('<option>'+x+'</option>' for x in ['Блоки','Оружие','Инструменты','Одежда и броня','Еда','Свет','Материалы'])+'''</select><button id="reset">Сбросить выбор</button></div><small id="visible"></small></header><main>'''+''.join(cards)+'''</main><footer>В новых мирах: деревни с колодцем, пограничные замки, разрушенные усадьбы, сломанные башни, лагеря и шахты под пещерными входами. Они не требуют новых текстур — используют существующие строительные материалы.<br>Также в исходниках есть жители с торговлей и приручаемый кот, олень, заяц, кабан, одежда и броня персонажей, факел в левой руке и переработанный Страж корней. Это не инвентарные предметы, поэтому в 98 карточек они не входят.<br>Песочница работает отдельно от срока прохождения главы: обязательное пробуждение в разрушенном доме, затем свободное выживание; сюжетные действия по взаимодействию. В новых мирах версии 6 добавлены физика предметов и сыпучих блоков, течение воды/лавы и отдельное здоровье частей тела. 200 достижений и аккаунт сохранены; текущая Windows-сборка ещё не пересобрана.</footer><aside><div class="inner"><strong id="count">Выбрано: 0</strong><textarea id="selection" readonly placeholder="Здесь появится список выбранных предметов"></textarea><button id="copy">Скопировать список</button></div></aside><script>const names='''+json.dumps(names,ensure_ascii=False)+''';const cards=[...document.querySelectorAll('.card')],search=document.querySelector('#search'),filter=document.querySelector('#category'),out=document.querySelector('#selection');function update(){let selected=cards.filter(c=>c.querySelector('input').checked).map(c=>names.find(x=>x.id===Number(c.dataset.id)));out.value=selected.map(x=>'#'+x.id+' '+x.name).join(', ');document.querySelector('#count').textContent='Выбрано: '+selected.length;let q=search.value.toLowerCase().trim(),cat=filter.value,n=0;for(let c of cards){c.hidden=!(c.dataset.name.includes(q)||c.dataset.id===q||('#'+c.dataset.id)===q)||(cat!=='Все категории'&&c.dataset.category!==cat);if(!c.hidden)n++}document.querySelector('#visible').textContent='Показано: '+n+' / '+cards.length}document.addEventListener('change',update);search.addEventListener('input',update);document.querySelector('#reset').onclick=()=>{cards.forEach(c=>c.querySelector('input').checked=false);update()};document.querySelector('#copy').onclick=()=>{out.select();try{document.execCommand('copy')}catch{}if(navigator.clipboard)navigator.clipboard.writeText(out.value).catch(()=>{});};update();</script></html>'''
(out/'Voxel-objects-catalog.html').write_text(page)
# Replace the obsolete giant overview with a compact current one; the HTML is the main deliverable.
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',12);canvas=Image.new('RGB',(980,((len(d['models'])+6)//7)*170),'#142129');draw=ImageDraw.Draw(canvas)
for i,m in enumerate(d['models']):
 x=(i%7)*140;y=(i//7)*170;im=Image.open(R/f'Assets/Resources/VoxelIcons/Item{m["id"]}.png').convert('RGBA').resize((132,132));canvas.paste(im,(x+4,y),im);name='#'+str(m['id'])+' '+m['name'];draw.text((x+4,y+134),name[:19],fill='#e4dfc7',font=font)
canvas.save(out/'Voxel-objects-catalog.jpg',quality=82,optimize=True)
print('Current offline model catalog:',len(cards),'cards;',len(page.encode()),'HTML bytes. No ZIP created.')
